package main

import (
    "encoding/json"
    "fmt"
)

type Product struct { Name string `json:"name"`; InStock bool `json:"inStock"` }
func main() {
    data, err := json.Marshal(Product{Name: "Notebook", InStock: true})
    if err != nil { panic(err) }
    fmt.Println(string(data))
}
